class Solution {
public:
    int numOfPairs(vector<string>& nums, string target) {
        unordered_map<string, int> count;
        for (const string& s : nums) count[s]++;
        int ans = 0;
        int tLen = target.size();
        for (int i = 1; i < tLen; ++i) {
            string p = target.substr(0, i);
            string s = target.substr(i);
            if (p == s) {
                ans += count[p] * (count[p] - 1);
            } else {
                ans += count[p] * count[s];
            }
        }
        return ans;
    }
};

class Solution {
    public int numOfPairs(String[] nums, String target) {
        Map<String, Integer> count = new HashMap<>();
        for (String s : nums) count.put(s, count.getOrDefault(s, 0) + 1);
        int ans = 0;
        for (int i = 1; i < target.length(); i++) {
            String p = target.substring(0, i);
            String s = target.substring(i);
            int cp = count.getOrDefault(p, 0);
            int cs = count.getOrDefault(s, 0);
            if (p.equals(s)) {
                ans += cp * (cp - 1);
            } else {
                ans += cp * cs;
            }
        }
        return ans;
    }
}

var numOfPairs = function(nums, target) {
  const count = new Map();
  for (const s of nums) count.set(s, (count.get(s) || 0) + 1);
  let ans = 0;
  for (let i = 1; i < target.length; i++) {
    const p = target.slice(0, i);
    const s = target.slice(i);
    const cp = count.get(p) || 0;
    const cs = count.get(s) || 0;
    if (p === s) {
      ans += cp * (cp - 1);
    } else {
      ans += cp * cs;
    }
  }
  return ans;
};
